  "(enables automatic room grouping).": "（启用按房间自动分组）。",
  "(optional): only this HA user will see the ⚙️ Configuration page. Leave it empty to show it to everyone.":
    "（可选）：只有这个 HA 用户能看到 ⚙️ 配置页。留空则所有人可见。",
