  "1 window open": "1 扇窗开着",
  "1 · What is it about": "1 · 是关于什么",
  "1. Open HA → click your": "1. 打开 HA → 点击你的",
  "10 hours": "10 小时",
  "12 Main Street": "主街 12 号",
  "12 V battery": "12 V 电瓶",
  "12 hours": "12 小时",
  "2 months": "2 个月",
  "2 · Where it happens": "2 · 在哪里发生",
