  "Fireplace pump": "壁炉水泵",
  "First configure the circles connected to Home. Each circle can use a direct power sensor or automatically sum every child of a load group. Then create the appliances inside each group. Empty or disabled nodes are not forced into the flow.":
    "先配置连到“首页”的圆圈。每个圆圈可以使用直接功率传感器，也可以自动汇总所属分组内的全部负载。然后在每个分组里创建家电。空的或已停用的节点不会被塞进流向图。",
  "First select your lights in the Lights step (or wizard).":
    "请先在“灯光”这一步（或向导里）选好你的灯。",
  Fixed: "固定",
  "Fixed cycle duration (minutes)": "固定程序时长（分钟）",
  "Flap opened": "投递口已打开",
  "Flightradar24 exposes “current in area”: the count, with the list of flights in the attributes.":
    "Flightradar24 提供“current in area”：数量，属性中附有航班列表。",
  "Flights in the area": "区域内航班",
  "Flights overhead": "头顶航班",
  "Flip the direction (ON = closed)": "反转方向（ON = 关闭）",
