  "Flow · Return · Pressure": "供水 · 回水 · 压力",
  "Flue extractor fan": "烟道排风机",
  "Flue gas": "烟气",
  "Flue gas fan": "烟气风机",
  "Flue gas temperature": "烟气温度",
