  "Leave it as the group icon to follow it; change it to tell this opening from the others.":
    "保持与分组图标一致即可跟随分组；修改它可把这个开口与其他区分开。",
  "Leave it empty and the circle is the total of the appliances below. Fill it in only if a clamp meter covers the whole line.":
    "留空的话，圆圈就是下面这些家电的合计。只有当钳形表覆盖整条回路时才填写。",
  "Leave it empty and the worst reading goes on the cover, which is the right answer when nothing is said. If your station already publishes its own index, put it here: the big number becomes its own, and the substances are read one by one by opening the card. The verdict still belongs to the worst reading — an index saying “good” must not hide a particulate saying “bad”.":
    "留空时封面显示最差的那项读数；什么都不说时，这就是正确答案。如果你的检测仪已经给出自己的综合指数，就填在这里：大数字变成它的，各项物质打开卡片逐一查看。判定仍然属于最差的读数——说“良好”的指数不该掩盖说“糟糕”的颗粒物。",
  "Leave it empty for something with no due date. With a date it shows up in the agenda, on its day.":
    "没有截止日期就留空。填了日期，它会出现在当天的日程里。",
  "Left on the Home Assistant language the dashboard follows the profile of whoever is looking. Picking one pins it for this dashboard, even when Home Assistant speaks another language.":
    "保持在 Home Assistant 的语言上，面板会跟随正在查看的人的配置。选定一种就会固定给这个面板，即使 Home Assistant 说的是另一种语言。",
