  "Turn everything on": "全部打开",
  "Turn it off to open on the first tap: whoever opens their own front door ten times a day knows the confirmation by heart. A PIN is not a confirmation and stays: a protected door keeps asking for it.":
    "想一触即开就把它关掉：每天开自家大门十次的人，早把确认背下来了。PIN 不是确认，会保留：受保护的门仍然会问。",
  "Turn off": "关闭",
  "Turn on": "打开",
  "Turn on or off": "打开或关闭",
  "Turn on/off": "开/关",
  "Turn the boiler on or off": "开或关锅炉",
  "Turning them on and off": "打开和关闭",
  Tuxedo: "礼服",
  "Two shots of the same car: the dashboard shows the plugged-in one while it charges and the other one the rest of the time. The first is enough — without the second it simply stays.":
    "同一辆车的两张照片：充电时面板显示插着充电线的那张，其余时间显示另一张。只填第一张也可以，没有第二张时它就一直留着。",
  "Two weeks that repeat, written by hand: tap a day and pick what goes out. No sensor and no Home Assistant calendar needed — the page and the Home tile read this exactly as they would read an integration. A material that already has its own sensor above is not repeated: the sensor wins.":
    "手写的、循环的两周：点一天，选那天拿出什么。不需要任何传感器，也不需要 Home Assistant 日历——页面和首页磁贴读它的方式，和读一个集成完全一样。上面已经有自己传感器的品类不会重复：以传感器为准。",
  Type: "类型",
  "Type / artwork": "类型 / 插画",
  "Type at least two letters: it searches every tab at once.":
    "请输入至少两个字符：一次搜索所有标签页。",
  "Type the code…": "输入密码…",
  "Type your question…": "输入你的问题…",
  "Tyre pressure": "胎压",
  Tyres: "轮胎",
  "Tyres fine": "轮胎正常",
  UNAVAILABLE: "不可用",
  UPS: "UPS",
  "Unable to sign WebRTC URL:": "无法为 WebRTC 地址签名：",
  Unavailable: "不可用",
  "Underfloor heating": "地暖",
  "Uninterruptible power supplies": "不间断电源",
  Unit: "设备",
  Unknown: "未知",
  Unlink: "取消关联",
  "Unlinked: the fields stay as they are, and the button at the bottom saves.":
    "已取消关联：字段保持原样，底部按钮保存。",
  Unlock: "解锁",
