  Unprotected: "未布防",
  Unread: "未读",
  "Unsaved changes": "有未保存的更改",
  "Until you pick the entity this opening is nowhere to be seen: not in the section, not on the tile, and the “in the widget” switch does not appear.":
    "在选择实体之前，这个出入口哪里都看不到：版块里没有，磁贴上也没有，“显示在小组件”的开关也不会出现。",
  "Until you pick what to press this button does not appear.":
    "在你选好要按什么之前，这个按钮不会出现。",
