  Uptime: "运行时长",
  "Use this device": "使用此设备",
  "Use your own entities for the weather station": "气象站使用自定义实体",
  "Used oil": "废油",
  "Uses the same catalog and blue icon as the first configuration.":
    "使用与首次配置相同的清单和相同的蓝色图标。",
