  "Negative when charging": "充电时为负",
  "With the sign the BMS uses: if it writes it negative while charging, pick that in “Current sign”.":
    "按 BMS 使用的符号：如果充电时写为负值，请在“电流符号”中选择。",
  "If the page says “Discharging” while the battery is charging, your BMS writes the current the other way round: pick “Negative when charging”.":
    "如果电池正在充电而页面显示“放电中”，说明你的 BMS 把电流写反了：请选择“充电时为负”。",
  "Remaining energy": "剩余能量",
  "Save pack": "保存电池组",
  "State of charge (SoC)": "电量 (SoC)",
  "State of health (SoH)": "健康状态 (SoH)",
  "Take the ${quanti} packs Home Assistant found": "导入 Home Assistant 找到的 ${quanti} 组电池",
  "The pack's charge percentage: without it the pack does not show.":
    "电池组的电量百分比：没有它电池组就不会显示。",
  "The storage packs and their BMS: they show in the Batteries tab of Energy and on the Battery storage tile in Home. One pack per row: its entity is the state of charge, and inside are the others — health, voltages, currents, temperatures, cycles, capacity and every single cell.":
    "储能的电池组及其 BMS：显示在“能源”的“电池”标签和主页的“储能电池”卡片中。每行一个电池组：其实体是电量，里面是其他实体——健康度、电压、电流、温度、循环次数、容量以及每一节电芯。",
  "to the house": "流向家中",
  "Unit of a hand-written capacity": "手动填写的容量单位",
  "Unnamed pack": "未命名电池组",
  "Until you pick the state of charge this pack is nowhere: not in Energy, not on the Home tile.":
    "在你选择电量之前，这个电池组不会出现在任何地方：既不在“能源”中，也不在主页卡片上。",
  "When the highest and lowest cells are further apart than this, the pack says “Needs balancing” and the Home tile asks for attention.":
    "当最高和最低电芯的差距超过此值时，电池组会显示“需要均衡”，主页卡片会提醒你注意。",
  "${accese} of ${totale} lights on": "${accese}/${totale} 盏灯已开",
  "${lettura.posizione}% open": "已打开 ${lettura.posizione}%",
  "1 of ${totale} lights on": "1/${totale} 盏灯已开",
  "Everything with its own control, in a grid": "每个设备都有自己的控制，以网格显示",
  "How an open room looks on the Rooms page.": "房间页面中打开的房间的显示方式。",
  "Room view": "房间视图",
  "the light is off": "灯已关",
  "the light is on": "灯已开",
  "The list split by type, as before": "按类型分组的列表，与之前相同",
