  "Also on: ${nomi}": "同时运行：${nomi}",
  "at ${ora}": "${ora}",
  "Buttons in Cooking": "烹饪中的按钮",
  "Cooking — status, times, temperature and controls": "烹饪 — 状态、时间、温度和控制",
  "Cooking shows up once the appliances include an air fryer, an oven, a microwave, a cooktop or a hood.":
    "当家电中有空气炸锅、烤箱、微波炉、灶台或抽油烟机时，就会出现“烹饪”。",
  "Cooking status": "烹饪状态",
  Cooler: "降温",
  "done at ${ora}": "${ora} 完成",
  "Done at ${ora}": "${ora} 完成",
  "Door closed": "门已关",
  "Drawer closed": "炸篮已关",
  "Drawer open": "炸篮已开",
  "Drawer or door": "炸篮或门",
  "Empty: uses the “Program state entity”.": "留空：使用“程序状态实体”。",
  "Entity for the services": "用于服务的实体",
  "Fill in from the appliance's entities": "从家电的实体中填写",
