  "Valve (valve) or switch (switch); empty uses valve.chiave_solare_termico":
    "阀门（valve）或开关（switch）；留空则使用 valve.chiave_solare_termico",
  "Valve with a position (cover): open above zero": "带位置的阀门（cover）：大于零即打开",
  Command: "命令",
