  "Add a partition": "添加分区",
  "Add a reading": "添加读数",
  "Alarm · ${quante} areas": "警报 · ${quante} 个区域",
  "Alarm partitions": "警报分区",
  "Buttons next to the readings: locks (lock and unlock), scripts, buttons, scenes, switches, blinds. A remote turns on and off; written remote.name:command it sends that command.":
    "读数旁的按钮：门锁（上锁和解锁）、脚本、按钮、场景、开关、百叶窗。遥控器（remote）可开关；写成 remote.name:command 则发送该命令。",
  "Empty: all the ones from the dashboard's Security section": "留空：仪表板安全部分中的全部",
  "Intercom / camera": "对讲 / 摄像头",
  "Leaving and who is home": "离家与在家人员",
